-- Paths and baseline are generated by the PowerShell bootstrap, not read from projects.
local config = vim.fs.dirname(debug.getinfo(1, "S").source:sub(2))
local deployment = vim.json.decode(table.concat(vim.fn.readfile(config .. "/deployment.json"), "\n"))
assert(deployment.schema == 1, "Unsupported bootstrap deployment metadata")
vim.fn.mkdir(vim.fn.stdpath("data"), "p")
vim.g.mapleader = " "
vim.g.maplocalleader = " "
vim.g.neovim_bootstrap = deployment
vim.env.PATH = table.concat(deployment.tool_directories, ";") .. ";" .. vim.env.PATH
vim.opt.rtp:prepend(deployment.plugin_root .. "/lazy.nvim")

local locks = vim.json.decode(table.concat(vim.fn.readfile(config .. "/lazy-lock.json"), "\n"))
local specs = dofile(config .. "/plugins.lua")
for _, spec in ipairs(specs) do
    local name = spec[1]:match("([^/]+)$")
    assert(locks[name], "Missing plugin lock: " .. name)
    spec.commit = locks[name].commit
    spec.dir = deployment.plugin_root .. "/" .. name
    spec.build = false
end

require("lazy").setup(specs, {
    root = deployment.plugin_root,
    lockfile = config .. "/lazy-lock.json",
    local_spec = false,
    install = { missing = false },
    checker = { enabled = false },
    change_detection = { enabled = false, notify = false },
    pkg = { enabled = false },
    rocks = { enabled = false },
    readme = { enabled = false },
    performance = { cache = { enabled = false } },
})

vim.keymap.set("n", "<leader>e", "<Cmd>Neotree toggle<CR>", { desc = "File tree" })
vim.keymap.set("n", "<leader>d", vim.diagnostic.open_float, { desc = "Diagnostic details" })
vim.keymap.set("n", "<leader>f", function()
    local conform = require("conform")
    if #conform.list_formatters(0) == 0 then
        vim.notify("No formatter configured. Language tooling is deferred from Phase 1.", vim.log.levels.INFO)
        return
    end
    conform.format({ async = true, lsp_format = "never" })
end, { desc = "Format buffer" })

vim.api.nvim_create_autocmd("LspAttach", {
    group = vim.api.nvim_create_augroup("BootstrapLspMappings", { clear = true }),
    callback = function(event)
        local mappings = {
            { "gd", vim.lsp.buf.definition, "Definition" },
            { "gr", vim.lsp.buf.references, "References" },
            { "K", vim.lsp.buf.hover, "Hover" },
            { "<leader>rn", vim.lsp.buf.rename, "Rename" },
            { "<leader>ca", vim.lsp.buf.code_action, "Code action" },
        }
        for _, mapping in ipairs(mappings) do
            vim.keymap.set("n", mapping[1], mapping[2], { buffer = event.buf, desc = mapping[3] })
        end
    end,
})
